import type {NextConfig} from "next";

const nextConfig: NextConfig = {
    // The app's user data still lives entirely in the browser. A server
    // runtime is required only for the optional Web Push relay (`/v1/*`), so
    // this is a normal Next.js server build rather than a static export.
    //
    // The offline worker is generated by `serwist build` (see
    // `serwist.config.ts` and the `build` script). We intentionally do not use
    // `withSerwistInit` here: Next 16 builds with Turbopack by default, which
    // `@serwist/next`'s webpack hook does not support. Serwist's configurator
    // mode is the Turbopack-compatible path and runs after `next build`.
    //
    // `web-push` is a CommonJS package that expects Node built-ins; keeping it
    // external avoids bundling its crypto/HTTP internals into the route.
    serverExternalPackages: ["web-push"],
    // The app only uses static icons/manifest images; skipping the image
    // optimizer keeps the server surface minimal and the PWA fully offline.
    images: {
        unoptimized: true,
    },
    experimental: {
        // Keeps navigations/fetches pending while offline and retries once
        // connectivity returns, instead of throwing in the client.
        useOffline: true,
    },
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;
